    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0RC1RD_0LC1LD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1]).
