  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S0 DR StB end.

(** Its mirror 1LB1RA_1RA0LC_1RD0LC_0RD0LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S0 DL StC
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_1LA0RC_1LD0RC_0LD0RB : list Instr := [(StA, S1)].
Definition tmw_1RB1LA_1LA0RC_1LD0RC_0LD0RB : TM := tm_wrap_trs tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB pins_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
Local Notation tm := tmw_1RB1LA_1LA0RC_1LD0RC_0LD0RB.

Lemma mirror_ok_1RB1LA_1LA0RC_1LD0RC_0LD0RB : mirror_tm tm_1RB1LA_1LA0RC_1LD0RC_0LD0RB = tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB (p : positive) : cconf := (StB, (Kp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [S1] [] 0 0 []) S0 (mkS [S0] [] 0 0 []).
Definition chz_1RB1LA_1LA0RC_1LD0RC_0LD0RB : list lstep := [SWinR 6].

Lemma run_z_1RB1LA_1LA0RC_1LD0RC_0LD0RB : srun tm false true chz_1RB1LA_1LA0RC_1LD0RC_0LD0RB Z0_1RB1LA_1LA0RC_1LD0RC_0LD0RB = Some (Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB, 0, 6).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [S1] [S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [S0] [S0] 1 0 [S1]) S0 (mkS [S0] [] 0 0 []).
Definition chp_1RB1LA_1LA0RC_1LD0RC_0LD0RB : list lstep := [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 3].

Lemma run_p_1RB1LA_1LA0RC_1LD0RC_0LD0RB : srun tm false true chp_1RB1LA_1LA0RC_1LD0RC_0LD0RB P0_1RB1LA_1LA0RC_1LD0RC_0LD0RB = Some (P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB, 2, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [S1] [S1] 1 0 [S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB : sconf := mkC StB (mkS [] [S0] 1 1 [S1]) S0 (mkS [S0] [] 0 0 []).
Definition cho_1RB1LA_1LA0RC_1LD0RC_0LD0RB : list lstep := [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 3; SFoldL 1].

Lemma run_ovf_1RB1LA_1LA0RC_1LD0RC_0LD0RB : srun tm true true cho_1RB1LA_1LA0RC_1LD0RC_0LD0RB B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB = Some (B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB, 2, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB, cden, Z0_1RB1LA_1LA0RC_1LD0RC_0LD0RB, Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\
  lift (cden (Kp q0 ++ [S0]) [] j P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB, cden, P0_1RB1LA_1LA0RC_1LD0RC_0LD0RB, P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_1LA0RC_1LD0RC_0LD0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 6), (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB1LA_1LA0RC_1LD0RC_0LD0RB Z0_1RB1LA_1LA0RC_1LD0RC_0LD0RB Z1_1RB1LA_1LA0RC_1LD0RC_0LD0RB 0 6
             run_z_1RB1LA_1LA0RC_1LD0RC_0LD0RB (Kp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j' q0 E) as (HA & HB).
    exists (2 * j' + 8), (cden (Kp q0 ++ [S0]) [] j' P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB1LA_1LA0RC_1LD0RC_0LD0RB P0_1RB1LA_1LA0RC_1LD0RC_0LD0RB P1_1RB1LA_1LA0RC_1LD0RC_0LD0RB 2 8
             run_p_1RB1LA_1LA0RC_1LD0RC_0LD0RB (Kp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB, cden, B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB
             = (StB, (rep [S0] (S j) ++ [S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_1LA0RC_1LD0RC_0LD0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LA_1LA0RC_1LD0RC_0LD0RB. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LA0RC_1LD0RC_0LD0RB B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB B1_1RB1LA_1LA0RC_1LD0RC_0LD0RB 2 8 p j' [] []).
    + exact run_ovf_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j' E).
    + exact (geo_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LA_1LA0RC_1LD0RC_0LD0RB : stepn tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB 10 InitES = Some (lift (Cc 2)).
Proof.
  assert (H : match csteps tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB 10 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LA_1LA0RC_1LD0RC_0LD0RB : existsb (fun tg => cfires tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB c0 10 tg) pins_1RB1LA_1LA0RC_1LD0RC_0LD0RB = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LA0RC_1LD0RC_0LD0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1LA0RC_1LD0RC_0LD0RB : forall t, ~ In t pins_1RB1LA_1LA0RC_1LD0RC_0LD0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 3; SCycL 1 0; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 3; SCycL 1 0; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LA0RC_1LD0RC_0LD0RB [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB1LA_1LA0RC_1LD0RC_0LD0RB : NonHalt tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\ QHBoundTr 32779478 tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\ QuasiHaltsTr tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
Proof.
  apply (lap_qh_stage tmm_1RB1LA_1LA0RC_1LD0RC_0LD0RB pins_1RB1LA_1LA0RC_1LD0RC_0LD0RB Cc 2 10 32779478).
  - exact bootq_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
  - intros p _. apply lap_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
  - intros t Ht p _. apply fire_1RB1LA_1LA0RC_1LD0RC_0LD0RB. exact Ht.
  - exact wit_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
  - apply qcleb_QC_18. reflexivity.
Qed.

Theorem qhtr_1RB1LA_1LA0RC_1LD0RC_0LD0RB : NonHalt tm_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\ QHBoundTr 32779478 tm_1RB1LA_1LA0RC_1LD0RC_0LD0RB /\ QuasiHaltsTr tm_1RB1LA_1LA0RC_1LD0RC_0LD0RB.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB1LA_1LA0RC_1LD0RC_0LD0RB). rewrite mirror_ok_1RB1LA_1LA0RC_1LD0RC_0LD0RB. exact qhtrm_1RB1LA_1LA0RC_1LD0RC_0LD0RB. Qed.

