Definition pins_1RB1LA_1LB1LC_1RD0LC_0RD1LA : list Instr := [(StA, S1); (StB, S0)].
Definition tmw_1RB1LA_1LB1LC_1RD0LC_0RD1LA : TM := tm_wrap_trs tm_1RB1LA_1LB1LC_1RD0LC_0RD1LA pins_1RB1LA_1LB1LC_1RD0LC_0RD1LA.
