(** ** The certificate *)

Definition A0_1RB1LA_1LB1LC_1RD0LC_0RD1LA : sconf := mkC StA (mkS [] [S1] 1 0 [S0]) S0 (mkS [S1;S1;S1] [] 0 0 []).
