    apply (fireo_1RB1LA_1LC0RB_0LC0RD_1LA1RD [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB1LA_1LC0RB_0LC0RD_1LA1RD : NonHalt tmm_1RB1LA_1LC0RB_0LC0RD_1LA1RD /\ QHBoundTr 32779478 tmm_1RB1LA_1LC0RB_0LC0RD_1LA1RD /\ QuasiHaltsTr tmm_1RB1LA_1LC0RB_0LC0RD_1LA1RD.
