  apply (lap_qh_stage tmm_1RB1LA_1LC0RB_0LC0RD_1LA1RD pins_1RB1LA_1LC0RB_0LC0RD_1LA1RD Cc 2 13 32779478).
  - exact bootq_1RB1LA_1LC0RB_0LC0RD_1LA1RD.
  - intros p _. apply lap_1RB1LA_1LC0RB_0LC0RD_1LA1RD.
  - intros t Ht p _. apply fire_1RB1LA_1LC0RB_0LC0RD_1LA1RD. exact Ht.
  - exact wit_1RB1LA_1LC0RB_0LC0RD_1LA1RD.
  - apply qcleb_QC_18. reflexivity.
Qed.

Theorem qhtr_1RB1LA_1LC0RB_0LC0RD_1LA1RD : NonHalt tm_1RB1LA_1LC0RB_0LC0RD_1LA1RD /\ QHBoundTr 32779478 tm_1RB1LA_1LC0RB_0LC0RD_1LA1RD /\ QuasiHaltsTr tm_1RB1LA_1LC0RB_0LC0RD_1LA1RD.
