Definition chn_1RB1LA_1LC0RB_1LD0RA_0LC1LA : list lstep := [SWin 12; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_inner_1RB1LA_1LC0RB_1LD0RA_0LC1LA : srun tm false true chn_1RB1LA_1LC0RB_1LD0RA_0LC1LA AI0_1RB1LA_1LC0RB_1LD0RA_0LC1LA = Some (AI1_1RB1LA_1LC0RB_1LD0RA_0LC1LA, 4, 16).
