(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_1LC0RB_1LD0RA_0LC1LA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S0;S1;S0] [] 0 0 []).
Definition chb_1RB1LA_1LC0RB_1LD0RA_0LC1LA : list lstep := [SWin 2; SWinR 10; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_boot_1RB1LA_1LC0RB_1LD0RA_0LC1LA : srun tm true true chb_1RB1LA_1LC0RB_1LD0RA_0LC1LA B0_1RB1LA_1LC0RB_1LD0RA_0LC1LA = Some (BB1_1RB1LA_1LC0RB_1LD0RA_0LC1LA, 4, 17).
