(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_1LC0RB_1LD0RA_0LC1LA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S0;S0;S1] [] 0 0 []).
