  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LC1RD_0RA0RB_0LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LC1RD_0RA0RB_0LA0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1LC1RD_0RA0RB_0LA0RB : forall t, ~ In t pins_1RB1LA_1LC1RD_0RA0RB_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
