    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_0RA0RB_0LA0RB [SWin 1; SWinR 3; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
