    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_0RA1RA_0LA0RB [SWin 1; SWinR 2] (StA, S1) ltac:(vm_compute; reflexivity)
