    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC1RD_0RB0LC_0LA0RB B0_1RB1LA_1LC1RD_0RB0LC_0LA0RB B1_1RB1LA_1LC1RD_0RB0LC_0LA0RB 4 9 p j' [] []).
