  apply (lap_qh_stage tm_1RB1LA_1LC1RD_0RB0LC_0LA0RB pins_1RB1LA_1LC1RD_0RB0LC_0LA0RB Cc 2 23 32779478).
  - exact bootq_1RB1LA_1LC1RD_0RB0LC_0LA0RB.
  - intros p _. apply lap_1RB1LA_1LC1RD_0RB0LC_0LA0RB.
  - intros t Ht p _. apply fire_1RB1LA_1LC1RD_0RB0LC_0LA0RB. exact Ht.
  - exact wit_1RB1LA_1LC1RD_0RB0LC_0LA0RB.
  - apply qcleb_QC_18. reflexivity.
Qed.

