(** ** The lap *)

Lemma lap_1RB1LA_1LC1RD_0RB0RD_0LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
