  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC1RD_0RB0RD_0LA0RB B0_1RB1LA_1LC1RD_0RB0RD_0LA0RB B1_1RB1LA_1LC1RD_0RB0RD_0LA0RB 4 9 p j' [] []).
    + exact run_ovf_1RB1LA_1LC1RD_0RB0RD_0LA0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC1RD_0RB0RD_0LA0RB p j' E).
    + exact (geo_1RB1LA_1LC1RD_0RB0RD_0LA0RB p j' E).
    + lia.
Qed.

