  - intros t Ht p _. apply fire_1RB1LA_1LC1RD_0RB0RD_0LA0RB. exact Ht.
  - exact wit_1RB1LA_1LC1RD_0RB0RD_0LA0RB.
  - apply qcleb_QC_18. reflexivity.
